const now = new Date();
const moisAnnee = now.toLocaleDateString('fr-FR', { month: 'long', year: 'numeric', timeZone: 'Europe/Paris' });
const moisAnneeCap = moisAnnee.charAt(0).toUpperCase() + moisAnnee.slice(1);

return [{
  json: {
    moisAnnee,
    moisAnneeCap,
    docTitleQuery: "immobilière - " + moisAnnee,
    outputFileName: "Newsletter immobilière - " + moisAnnee + ' (HTML email).html',
    heroTitle: "Le tour d'horizon du mois",
    heroSubtitle: "Taux, fiscalité, travaux et confort thermique : les actualités du mois, sélectionnées et expliquées pour vous."
  }
}];

const res = $json;
const files = res.files || [];
const prep = $('Préparer la recherche').first().json;
if (files.length === 0) {
  throw new Error("Aucun document newsletter trouvé pour " + prep.moisAnnee + ". Vérifiez qu'il existe dans le dossier Newsletters avec le bon titre.");
}
return [{ json: { documentId: files[0].id, documentName: files[0].name } }];

const doc = $json;
const content = (doc.body && doc.body.content) ? doc.body.content : [];
const paragraphs = [];
for (const el of content) {
  if (!el.paragraph) continue;
  const text = (el.paragraph.elements || [])
    .map(e => (e.textRun && e.textRun.content) || '')
    .join('')
    .replace(/\n$/, '');
  paragraphs.push(text);
}

const isHeader = (s) => /^—\s.+\s—$/.test(s.trim());
const headerIdx = [];
paragraphs.forEach((p, i) => { if (isHeader(p)) headerIdx.push(i); });

let apporteurPos = -1, recrutementPos = -1;
headerIdx.forEach(i => {
  const up = paragraphs[i].toUpperCase();
  if (up.indexOf('APPORTEUR') !== -1) apporteurPos = i;
  if (up.indexOf('REJOINDRE') !== -1 || up.indexOf('EQUIPE') !== -1 || up.indexOf('ÉQUIPE') !== -1) recrutementPos = i;
});

const articleHeaderIdx = headerIdx.filter(i => i !== apporteurPos && i !== recrutementPos);

const sections = [];
for (let k = 0; k < articleHeaderIdx.length; k++) {
  const hIdx = articleHeaderIdx[k];
  let nextIdx;
  if (k + 1 < articleHeaderIdx.length) nextIdx = articleHeaderIdx[k + 1];
  else if (apporteurPos !== -1) nextIdx = apporteurPos;
  else if (recrutementPos !== -1) nextIdx = recrutementPos;
  else nextIdx = paragraphs.length;

  const label = paragraphs[hIdx].replace(/^—\s*/, '').replace(/\s*—$/, '').trim();
  const body = paragraphs.slice(hIdx + 1, nextIdx).filter(p => p !== '');
  const titre = body[0] || '';
  const synthese = body[1] || '';
  const sourceLine = body.find(p => /^Source\s*:/i.test(p)) || '';
  const urlMatch = sourceLine.match(/https?:\/\/\S+/);
  const source_url = urlMatch ? urlMatch[0] : '';

  let sec = sections.find(s => s.label === label);
  if (!sec) { sec = { label, articles: [] }; sections.push(sec); }
  sec.articles.push({ titre, synthese, source_url });
}

function parseCta(headerPos, endPos) {
  if (headerPos === -1) return { intro: '', paragraphs: [] };
  const raw = paragraphs.slice(headerPos + 1, endPos).filter(p => p !== '');
  return { intro: raw[0] || '', paragraphs: raw.slice(1) };
}

const apporteurEnd = recrutementPos !== -1 ? recrutementPos : paragraphs.length;
const apporteur = parseCta(apporteurPos, apporteurEnd);
const recrutement = parseCta(recrutementPos, paragraphs.length);

if (sections.length === 0) {
  throw new Error('Impossible de trouver des articles dans le document. Le format du document a-t-il changé ?');
}

return [{
  json: {
    titre_doc: paragraphs[0] || '',
    sections,
    apporteur,
    recrutement
  }
}];

const data = $json;
const apporteur = data.apporteur;
const recrutement = data.recrutement;

const systemPrompt = "Tu mets en forme, en HTML pret pour un email, le contenu de deux encarts d'appel a l'action (CTA) pour la newsletter immobiliere d'un consultant effiCity. On te fournit pour chaque encart une introduction (une phrase d'accroche) et une liste de paragraphes de texte fournis par l'utilisateur, a respecter fidelement (ne jamais reformuler, raccourcir ou supprimer d'information).

Pour CHAQUE encart (apporteur et recrutement), produis un fragment HTML fait uniquement de balises <p> (et eventuellement <ul>/<li> si le texte contient une liste a puces introduite par des tirets), en respectant ces gabarits exacts :
- paragraphe normal : <p style="margin:0 0 10px 0;font-family:'Source Sans 3','Source Sans Pro',Helvetica,Arial,sans-serif;font-size:14px;line-height:1.55;color:#3F444A;">...</p>
- paragraphe contenant LE chiffre cle le plus marquant (pourcentage ou montant en euros), au plus un par encart : <p style="margin:0 0 10px 0;font-family:'Source Sans 3','Source Sans Pro',Helvetica,Arial,sans-serif;font-size:14px;line-height:1.55;color:#23262A;font-weight:700;">...</p>
- le DERNIER paragraphe de l'encart utilise margin:0 0 16px 0 au lieu de margin:0 0 10px 0
- liste a puces eventuelle : <ul style="margin:0 0 12px 0;padding:0 0 0 18px;font-family:'Source Sans 3','Source Sans Pro',Helvetica,Arial,sans-serif;font-size:14px;line-height:1.6;color:#3F444A;"><li>...</li></ul>
- si le texte mentionne explicitement un site web ou une adresse email, transforme cette mention en lien : <a href="https://exemple.com/" style="color:#3B7A20;font-weight:700;text-decoration:none;">exemple.com</a> (ajoute le protocole https:// s'il est absent). N'invente jamais d'URL non mentionnee dans le texte fourni.

Determine aussi, pour chaque encart, le lien principal du bouton d'action (button_href) : l'URL du site mentionne dans le texte si elle existe, sinon "mailto:rlacamoire@efficity.com". Choisis un intitule de bouton court et naturel (button_label), par exemple "Devenir apporteur" ou "Nous rejoindre".

Reponds UNIQUEMENT avec un objet JSON valide (rien avant, rien apres), au format exact :
{"apporteur":{"heading":"Devenez apporteur d'affaires","html":"...","button_label":"...","button_href":"..."},"recrutement":{"heading":"Rejoignez l'equipe","html":"...","button_label":"...","button_href":"..."}}";

const userPrompt = "Encart apporteur d'affaires :
Introduction : " + apporteur.intro + "
Texte :
" + apporteur.paragraphs.join('

') +
  "

Encart recrutement :
Introduction : " + recrutement.intro + "
Texte :
" + recrutement.paragraphs.join('

');

return [{
  json: {
    claudeRequestBody: {
      model: 'claude-opus-5',
      max_tokens: 3000,
      system: systemPrompt,
      messages: [
        { role: 'user', content: userPrompt }
      ]
    }
  }
}];

const blocks = $json.content || [];
const textBlocks = blocks.filter(b => b.type === 'text');
const raw = textBlocks.length ? textBlocks[textBlocks.length - 1].text : '';
const cleaned = raw.trim().replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();

let data;
try {
  data = JSON.parse(cleaned);
} catch (e) {
  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');
  if (firstBrace === -1 || lastBrace === -1 || lastBrace < firstBrace) {
    throw new Error('Reponse Claude non parseable en JSON : ' + raw);
  }
  try {
    data = JSON.parse(cleaned.slice(firstBrace, lastBrace + 1));
  } catch (e2) {
    throw new Error('Reponse Claude non parseable en JSON : ' + raw);
  }
}

return [{ json: data }];

const prep = $('Préparer la recherche').first().json;
const structure = $('Extraire la structure').first().json;
const cta = $json;

function esc(s) { return (s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }

