';
    }
    sectionsHtml += '<tr><td class="px" style="padding:' + topPad + 'px 40px 0 40px;">
  <h2 style="margin:0 0 8px 0;font-family:'Source Sans 3','Source Sans Pro',Helvetica,Arial,sans-serif;font-size:17px;line-height:1.35;font-weight:700;color:#23262A;">' + esc(art.titre) + '</h2>
  <p style="margin:0 0 10px 0;font-family:'Source Sans 3','Source Sans Pro',Helvetica,Arial,sans-serif;font-size:14.5px;line-height:1.6;color:#3F444A;">' + esc(art.synthese) + '</p>';
    if (art.source_url) {
      sectionsHtml += '
  <a href="' + esc(art.source_url) + '" style="font-family:'Source Sans 3','Source Sans Pro',Helvetica,Arial,sans-serif;font-size:13px;font-weight:700;color:#3B7A20;text-decoration:none;">Lire l'article&nbsp;&rarr;</a>';
    }
    sectionsHtml += '
</td></tr>
';
  });
});

