    <td style="border-left:3px solid #4C9A2A;padding:22px 24px;">
      <h3 style="margin:0 0 10px 0;font-family:'Source Sans 3','Source Sans Pro',Helvetica,Arial,sans-serif;font-size:16px;font-weight:700;color:#23262A;">' + esc(cardData.heading) + '</h3>
      ' + cardData.html + '
      <table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="background-color:#4C9A2A;"><a href="' + esc(cardData.button_href) + '" style="display:inline-block;padding:10px 20px;font-family:'Source Sans 3','Source Sans Pro',Helvetica,Arial,sans-serif;font-size:14px;font-weight:700;color:#FFFFFF;text-decoration:none;">' + esc(cardData.button_label) + '</a></td></tr></table>
    </td>
  </tr></table>
</td></tr>
';
}

const apporteurHtml = ctaCardHtml(36, cta.apporteur);
